func checkTaskAnswersValue(in *TaskAnswers) error {
	if in == nil {
		return fmt.Errorf("missing root value")
	}
	active := make(map[any]bool)
	if err := checkTaskAnswersTaskAnswersValue(in, "$", active); err != nil {
		return err
	}
	return nil
}

// checkTaskAnswersTaskAnswersValue checks one generated value on the active path.
func checkTaskAnswersTaskAnswersValue(in *TaskAnswers, field string, active map[any]bool) error {
	if in == nil {
		return nil
	}
	if active[in] {
		return fmt.Errorf("%s: cyclic Go value", field)
	}
	active[in] = true
	defer delete(active, in)
	if in != nil {
		if !utf8.ValidString(string(in.TaskID)) {
			return fmt.Errorf("%s: invalid UTF-8", generatedJSONChildPath(field, "task_id", false))
		}
		for key1, item1 := range in.Responses {
			_ = item1
			if !utf8.ValidString(string(key1)) {
				return fmt.Errorf("%s: invalid UTF-8 map key", generatedJSONChildPath(field, "responses", false))
			}
		}
	}
	return nil
}
